for k,a in pairs(areas) do P.GatherAreas[k]=a end
for k,a in pairs(nodes) do P.GatherNodeData.areas[k]=a end
for id,n in pairs(npcs) do P.NPCSources[id]=n end
for k,a in pairs(zones) do P.GatherZoneAreas[k]=a end
local function add(t,v) for _,x in ipairs(t) do if x==v then return end end;t[#t+1]=v end
for _,entries in pairs(P.GatherAtlas) do for _,e in ipairs(entries) do
 local p=patches[e.item]
 if p then
  local sources,seen={},{}
  for _,s in ipairs(e.sources or {}) do sources[#sources+1]=s;seen[s.kind..":"..s.id..":"..s.method]=true end
  for _,s in ipairs(p.sources) do if not seen[s.kind..":"..s.id..":"..s.method] then sources[#sources+1]=s end end
  e.sources=sources;e.skinReferenceCount=p.added;e.mapKeys=e.mapKeys or {};e.referenceURLs=e.referenceURLs or {}
  local words={e.searchText or e.name}
  for _,s in ipairs(sources) do
   words[#words+1]=s.name;words[#words+1]=table.concat(s.zones or {}," ")
   for _,k in ipairs(s.mapKeys or {}) do add(e.mapKeys,k) end
  end
  e.searchText=table.concat(words," "):lower();add(e.referenceURLs,p.url)
  P.GatherZoneMaps[e.key]=choices[e.item]
 end
end end
